    conditions_checksum: `checksum-${scenario}`,
    map_name: "m",
    scenario_name: scenario,
    episodes: 10,
    success_rate: successRate,
    collision_rate: 0,
    mean_travel_time: 10,
    mean_path_efficiency: 1,
    mean_smoothness: 0.1,
    worst_min_clearance: 0.5,
    mean_local_planning_latency: 0.005,
